using namespace std;

int main() {
    unsigned long long l1, r1, l2, r2, k;
    cin >> l1 >> r1 >> l2 >> r2 >> k;

    unsigned long long left = max(l1, l2);
    unsigned long long right = min(r1, r2);

    if (left > right) {
        cout << 0;
    } else {
        unsigned long long answer = right - left + 1;
        if (left <= k && k <= right) {
            --answer;
        }
        cout << answer;
    }

    return 0;
}

